// expect: nodes: 5
// expect: edges: 3
// expect: reachable_from(0) = 4
// expect: components = 2

type Marks {
    cells: Int[] = [];
}

fn makeMarks(n: Int) -> Marks {
    let m: Marks = new Marks();
    loop i in 0..n { m.cells = m.cells + [0]; }
    ret m;
}

fn dfs(adj: Int[], visited: Marks, n: Int, u: Int) -> Int {
    visited.cells[u] = 1;
    let count: Int = 1;
    loop v in 0..n {
        if adj[u * n + v] == 1 {
            if visited.cells[v] == 0 { count = count + dfs(adj, visited, n, v); }
        }
    }
    ret count;
}

fn reachableFrom(adj: Int[], n: Int, src: Int) -> Int {
    let visited: Marks = makeMarks(n);
    ret dfs(adj, visited, n, src);
}

fn componentCount(adj: Int[], n: Int) -> Int {
    let visited: Marks = makeMarks(n);
    let comps: Int = 0;
    loop s in 0..n {
        if visited.cells[s] == 0 {
            comps = comps + 1;
            let ignore: Int = dfs(adj, visited, n, s);
        }
    }
    ret comps;
}

fn countEdges(adj: Int[], n: Int) -> Int {
    let total: Int = 0;
    loop u in 0..n {
        loop v in 0..n {
            if adj[u * n + v] == 1 { total = total + 1; }
        }
    }
    ret total / 2;
}

