    let results: Report[] = [];

    loop i in 0..length(nums) {
        let n: Int = nums[i];
        let p: Bool = is_prime(n);
        let f: Int = factorial(n);

        let r: Report = new Report { number: n, is_prime: p, fact: f };
        results = results + [r];
    }

    fx {
        println("Number | Prime | Factorial");
        println("---------------------------");
        loop i in 0..length(results) {
            let r: Report = results[i];
            let p_str: Text = if r.is_prime { "Yes" } else { "No" };
            println(r.number, " | ", p_str, " | ", r.fact);
        }
    }

    ret;
}

