// Follow a four-digit number into Kaprekar's constant.

@pre n >= 0
@post length(result) == 4
fn digits4(n: Int) -> Int[] {
    let value: Int = n % 10000;
    let digits: Int[] = [];
    digits = digits + [value div 1000];
    digits = digits + [(value div 100) % 10];
    digits = digits + [(value div 10) % 10];
    digits = digits + [value % 10];
    ret digits;
}

@pre length(digits) == 4
@post length(result) == 4
fn sort4(digits: Int[]) -> Int[] {
    let sorted: Int[] = digits;
    let pass: Int = 0;
    loop pass < 4 {
        let j: Int = 0;
        loop j < 3 {
            if sorted[j] > sorted[j + 1] {
                let temp: Int = sorted[j];
                sorted[j] = sorted[j + 1];
                sorted[j + 1] = temp;
            }
            j = j + 1;
        }
        pass = pass + 1;
    }
    ret sorted;
}

@pre length(digits) == 4
fn ascendingNumber(digits: Int[]) -> Int {
    ret digits[0] * 1000 + digits[1] * 100 + digits[2] * 10 + digits[3];
}

@pre length(digits) == 4
fn descendingNumber(digits: Int[]) -> Int {
    ret digits[3] * 1000 + digits[2] * 100 + digits[1] * 10 + digits[0];
}

@pre n >= 0 && n <= 9999
@post result >= 0
fn kaprekarStep(n: Int) -> Int {
    let ordered: Int[] = sort4(digits4(n));
    ret descendingNumber(ordered) - ascendingNumber(ordered);
}

fn main() -> Void {
    let value: Int = 3524;
    let steps: Int = 0;

    fx {
        println("Kaprekar walk from ", value);
    }

    loop value != 6174 && steps < 12 {
        let next: Int = kaprekarStep(value);
        fx {
            println(value, " -> ", next);
        }
        value = next;
        steps = steps + 1;
        if value == 0 {
            break;
        }
    }

    fx {
        if value == 6174 {
            println("Reached 6174 in ", steps, " steps.");
        } else {
            println("Stopped at ", value, " after ", steps, " steps.");
        }
    }
    ret;
}

// Express a mass as a two-pan balance using powers of three.

@pre value >= 0
@post length(result) > 0
fn balancedDigits(value: Int) -> Int[] {
    let n: Int = value;
    let digits: Int[] = [];

    if n == 0 {
        digits = digits + [0];
        ret digits;
    }

    loop n > 0 {
        let remainder: Int = n % 3;
        if remainder == 2 {
            digits = digits + [-1];
            n = (n + 1) / 3;
        } else {
            digits = digits + [remainder];
            n = n / 3;
        }
    }
    ret digits;
}

fn main() -> Void {
    let mass: Int = 83;
    let digits: Int[] = balancedDigits(mass);
    let representation: Text = "";
    let index: Int = length(digits) - 1;

    loop index >= 0 {
        if digits[index] == 1 {
            representation = representation + "+";
        } else {
            if digits[index] == -1 {
                representation = representation + "-";
            } else {
                representation = representation + "0";
            }
        }
        index = index - 1;
    }

    fx {
        println(mass, " in balanced ternary is ", representation);
        println("Place the object on one pan, then:");
    }

    let power: Int = 1;
    let i: Int = 0;
    loop i < length(digits) {
        if digits[i] == 1 {
            fx {
                println("  put weight ", power, " on the opposite pan");
            }
        }
        if digits[i] == -1 {
            fx {
                println("  put weight ", power, " beside the object");
            }
        }
        power = power * 3;
        i = i + 1;
    }
    ret;
}

// Generate the look-and-say sequence by scanning one character at a time.

@pre string_len(source) > 0
@post string_len(result) > 0
fn nextTerm(source: Text) -> Text {
    let total: Int = string_len(source);
    let output: Text = "";
    let i: Int = 1;

    loop i <= total {
        let symbol: Text = copy(source, i, 1);
        let run: Int = 1;

        loop i + run <= total {
            let candidate: Text = copy(source, i + run, 1);
            if candidate != symbol {
                break;
            }
            run = run + 1;
        }

        output = output + itoa(run) + symbol;
        i = i + run;
    }
    ret output;
}

fn main() -> Void {
    let term: Text = "1";

    loop generation in 1..13 {
        fx {
            println(generation, ": ", term, "  length=", string_len(term));
        }
        term = nextTerm(term);
    }
    ret;
}

// Run Conway's Game of Life on a torus, so every edge wraps around.

@pure
fn cellIndex(x: Int, y: Int, width: Int) -> Int {
    ret y * width + x;
}

@pre width > 0
@pre height > 0
@pure
fn aliveAt(cells: Int[], x: Int, y: Int, width: Int, height: Int) -> Int {
    let wrappedX: Int = x;
    let wrappedY: Int = y;

    loop wrappedX < 0 {
        wrappedX = wrappedX + width;
    }
    loop wrappedX >= width {
        wrappedX = wrappedX - width;
    }
    loop wrappedY < 0 {
        wrappedY = wrappedY + height;
    }
    loop wrappedY >= height {
        wrappedY = wrappedY - height;
    }

    ret cells[cellIndex(wrappedX, wrappedY, width)];
}

@pre length(cells) == width * height
@post length(result) == width * height
@pure
fn nextGeneration(cells: Int[], width: Int, height: Int) -> Int[] {
    let output: Int[] = [];

    loop y in 0..height {
        loop x in 0..width {
            let neighbors: Int = 0;
            let dy: Int = -1;

            loop dy <= 1 {
                let dx: Int = -1;
                loop dx <= 1 {
                    if dx != 0 || dy != 0 {
                        neighbors = neighbors + aliveAt(cells, x + dx, y + dy, width, height);
                    }
                    dx = dx + 1;
                }
                dy = dy + 1;
            }

            let current: Int = cells[cellIndex(x, y, width)];
            let next: Int = 0;
            if current == 1 && (neighbors == 2 || neighbors == 3) {
                next = 1;
            }
            if current == 0 && neighbors == 3 {
                next = 1;
            }
            output = output + [next];
        }
    }
    ret output;
}

fn render(cells: Int[], width: Int, height: Int, generation: Int) -> Void {
    fx {
        println("generation ", generation);
    }

    loop y in 0..height {
        let line: Text = "";
        loop x in 0..width {
            if cells[cellIndex(x, y, width)] == 1 {
                line = line + "#";
            } else {
                line = line + ".";
            }
        }
        fx {
            println(line);
        }
    }
    ret;
}

fn main() -> Void {
    let width: Int = 20;
    let height: Int = 10;
    let total: Int = width * height;
    let cells: Int[] = [];

    loop i in 0..total {
        cells = cells + [0];
    }

    cells[cellIndex(1, 0, width)] = 1;
    cells[cellIndex(2, 1, width)] = 1;
    cells[cellIndex(0, 2, width)] = 1;
    cells[cellIndex(1, 2, width)] = 1;
    cells[cellIndex(2, 2, width)] = 1;

    let generation: Int = 0;
    loop generation < 8 {
        render(cells, width, height, generation);
        cells = nextGeneration(cells, width, height);
        generation = generation + 1;
    }
    ret;
}

// Demonstrate Efron's nontransitive dice: superiority forms a cycle.

@pre length(a) > 0
@pre length(b) > 0
@post result.0 >= 0
@post result.1 > 0
fn matchup(a: Int[], b: Int[]) -> (Int, Int) {
    let wins: Int = 0;
    let comparisons: Int = 0;

    loop i in 0..length(a) {
        loop j in 0..length(b) {
            if a[i] > b[j] {
                wins = wins + 1;
            }
            comparisons = comparisons + 1;
        }
    }
    ret (wins, comparisons);
}

fn report(nameA: Text, a: Int[], nameB: Text, b: Int[]) -> Void {
    let (wins, total) = matchup(a, b);
    let rate: Real = wins * 100.0 / total;
    fx {
        println(nameA, " beats ", nameB, " in ", wins, "/", total, " matchups (", rate:0:2, "%)");
    }
    ret;
}

