}

// Find the smallest positive integer expressible as two distinct sums of cubes.

@pre n >= 0
@pure
fn cube(n: Int) -> Int {
    ret n * n * n;
}

fn main() -> Void {
    let limit: Int = 20;
    let found: Bool = false;
    let a: Int = 1;

    loop a <= limit && !found {
        let b: Int = a;
        loop b <= limit && !found {
            let left: Int = cube(a) + cube(b);
            let c: Int = a + 1;

            loop c <= limit && !found {
                let d: Int = c;
                loop d <= limit && !found {
                    let right: Int = cube(c) + cube(d);
                    if left == right {
                        fx {
                            println(left, " = ", a, "^3 + ", b, "^3 = ", c, "^3 + ", d, "^3");
                        }
                        found = true;
                    }
                    d = d + 1;
                }
                c = c + 1;
            }
            b = b + 1;
        }
        a = a + 1;
    }

    if !found {
        fx {
            println("No taxicab number found below cube base ", limit);
        }
    }
    ret;
}

// Solve the alphametic TWO + TWO = FOUR using column carries.

@pure
fn allDistinct6(a: Int, b: Int, c: Int, d: Int, e: Int, f: Int) -> Bool {
    let digits: Int[] = [a, b, c, d, e, f];
    let i: Int = 0;

    loop i < length(digits) {
        let j: Int = i + 1;
        loop j < length(digits) {
            if digits[i] == digits[j] {
                ret false;
            }
            j = j + 1;
        }
        i = i + 1;
    }
    ret true;
}

fn main() -> Void {
    let f: Int = 1;
    let solutions: Int = 0;

    loop t in 2..10 {
        loop w in 0..10 {
            loop o in 0..10 {
                let r: Int = (2 * o) % 10;
                let carry1: Int = (2 * o) / 10;
                let u: Int = (2 * w + carry1) % 10;
                let carry2: Int = (2 * w + carry1) / 10;
                let hundreds: Int = 2 * t + carry2;

                if hundreds == o + 10 * f && allDistinct6(t, w, o, f, u, r) {
                    let two: Int = t * 100 + w * 10 + o;
                    let four: Int = f * 1000 + o * 100 + u * 10 + r;
                    fx {
                        println(two, " + ", two, " = ", four);
                    }
                    solutions = solutions + 1;
                }
            }
        }
    }

    fx {
        println("solutions = ", solutions);
    }
    ret;
}

// Compute Gregorian weekdays with integer arithmetic.

@pre year >= 1583
@pre month >= 1 && month <= 12
@pre day >= 1 && day <= 31
@post result >= 0 && result <= 6
fn weekdayIndex(year: Int, month: Int, day: Int) -> Int {
    let offsets: Int[] = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4];
    let adjustedYear: Int = year;
    if month < 3 {
        adjustedYear = adjustedYear - 1;
    }
    ret (adjustedYear + adjustedYear div 4 - adjustedYear div 100 + adjustedYear div 400 + offsets[month - 1] + day) % 7;
}

@pre index >= 0 && index <= 6
fn weekdayName(index: Int) -> Text {
    let names: Text[] = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
    ret names[index];
}

fn showDate(year: Int, month: Int, day: Int) -> Void {
    let index: Int = weekdayIndex(year, month, day);
    let name: Text = weekdayName(index);
    fx {
        println(year, "-", month, "-", day, " is a ", name);
    }
    ret;
}

