    loop i in 0..length(lines) {
        let level: Text = levelOf(lines[i]);
        let message: Text = messageOf(lines[i]);
        if level == "ERROR" {
            errors = errors + 1;
        }
        fx {
            println("[", level, "] ", message);
        }
    }
    fx {
        println("error count = ", errors);
    }
    ret;
}

// Dynamic-array statistics with real division and clamp

@pure
fn sumOf(xs: Int[]) -> Int {
    let total: Int = 0;
    loop i in 0..length(xs) {
        total = total + xs[i];
    }
    ret total;
}

@pure
fn minOf(xs: Int[]) -> Int {
    let best: Int = xs[0];
    loop i in 1..length(xs) {
        best = min(best, xs[i]);
    }
    ret best;
