// Sensor sweep — TOON array root, typed extraction, rollup record

type Sweep {
    total: Int = 0;
    hot: Int = 0;
    cold: Int = 0;
    ok: Int = 0;

    fn record(temp: Real) -> Text {
        self.total = self.total + 1;
        if temp >= 80.0 {
            self.hot = self.hot + 1;
            ret "HOT";
        }
        if temp <= 10.0 {
            self.cold = self.cold + 1;
            ret "COLD";
        }
        self.ok = self.ok + 1;
        ret "OK";
    }
}

fn main() -> Void {
