type Stack {
    items: Int[];

    fn push(val: Int) -> Void {
        self.items = self.items + [val];
        ret;
    }

    fn pop() -> Int {
        let top: Int = self.items[length(self.items) - 1];
        let newItems: Int[] = [];
        loop i in 0..length(self.items) - 1 {
            newItems = newItems + [self.items[i]];
        }
        self.items = newItems;
        ret top;
    }

    fn peek() -> Int {
        ret self.items[length(self.items) - 1];
    }

    fn size() -> Int {
        ret length(self.items);
    }
}

@pure
fn isOp(ch: Text) -> Bool {
    if ch == "+" { ret true; }
    if ch == "-" { ret true; }
    if ch == "*" { ret true; }
    if ch == "/" { ret true; }
    ret false;
}

fn evalRPN(tokens: Text[]) -> Int {
    let stack: Stack = new Stack { items: [] };

    loop i in 0..length(tokens) {
        let tok: Text = tokens[i];
        if isOp(tok) {
            let b: Int = stack.pop();
            let a: Int = stack.pop();
            let result: Int = 0;
            if tok == "+" { result = a + b; }
            if tok == "-" { result = a - b; }
            if tok == "*" { result = a * b; }
            if tok == "/" { result = a / b; }
            stack.push(result);
        } else {
            stack.push(parse_int(tok));
        }
    }
    ret stack.pop();
}

fn main() -> Void {
    let expr1: Text[] = ["2", "3", "+", "4", "*"];
    let expr2: Text[] = ["5", "1", "2", "+", "4", "*", "+", "3", "-"];

    fx {
        println("Expression: 2 3 + 4 * => ", evalRPN(expr1));
        println("Expression: 5 1 2 + 4 * + 3 - => ", evalRPN(expr2));
    }
    ret;
}

type Grid {
    width: Int;
    height: Int;
    cells: Int[];

    fn idx(r: Int, c: Int) -> Int {
        ret r * self.width + c;
    }

    fn alive(r: Int, c: Int) -> Bool {
        if r < 0 || r >= self.height || c < 0 || c >= self.width {
            ret false;
        }
        ret self.cells[self.idx(r, c)] == 1;
    }

    fn countNeighbors(r: Int, c: Int) -> Int {
        let count: Int = 0;
        let dr: Int = -1;
        loop dr <= 1 {
            let dc: Int = -1;
            loop dc <= 1 {
                if dr != 0 || dc != 0 {
                    if self.alive(r + dr, c + dc) {
                        count = count + 1;
                    }
                }
                dc = dc + 1;
            }
            dr = dr + 1;
        }
        ret count;
    }

    fn step() -> Grid {
        let next: Int[] = [];
        loop i in 0..self.width * self.height {
            next = next + [0];
        }
        let result: Grid = new Grid { width: self.width, height: self.height, cells: next };

        loop r in 0..self.height {
            loop c in 0..self.width {
                let n: Int = self.countNeighbors(r, c);
                let current: Int = self.cells[self.idx(r, c)];
                if current == 1 && (n == 2 || n == 3) {
                    result.cells[result.idx(r, c)] = 1;
                }
                if current == 0 && n == 3 {
                    result.cells[result.idx(r, c)] = 1;
                }
            }
        }
        ret result;
    }

    fn display() -> Void {
        loop r in 0..self.height {
            let line: Text = "";
            loop c in 0..self.width {
                if self.alive(r, c) {
                    line = line + "# ";
                } else {
                    line = line + ". ";
                }
            }
            fx { println(line); }
        }
        ret;
    }
}

fn main() -> Void {
    let w: Int = 10;
    let h: Int = 6;
    let cells: Int[] = [];
    loop i in 0..w * h {
        cells = cells + [0];
    }
    let grid: Grid = new Grid { width: w, height: h, cells: cells };

    grid.cells[grid.idx(1, 2)] = 1;
    grid.cells[grid.idx(2, 3)] = 1;
    grid.cells[grid.idx(3, 1)] = 1;
    grid.cells[grid.idx(3, 2)] = 1;
    grid.cells[grid.idx(3, 3)] = 1;

    let generations: Int = 5;
    loop gen in 0..generations {
        fx {
            println("--- Generation ", gen, " ---");
        }
        grid.display();
        grid = grid.step();
    }
    fx { println("--- Final ---"); }
    grid.display();
    ret;
}

// Line/word/char counter over an in-memory Text[] of lines. Aether exposes
// no readable "file variable" type from its own syntax (assign/reset/readln
// are real vm_builtins, but "First arg to Assign must be a file variable"
// -- there is no Aether-level file-content-read API), so this demonstrates
// the counting logic directly rather than pretending to open a real file.
fn main() -> Void {
    let lines: Text[] = [
        "the quick brown fox",
        "jumps over the lazy dog",
        "aether is a compact language"
    ];

    let lineCount: Int = 0;
    let wordCount: Int = 0;
    let charCount: Int = 0;

    loop li in 0..length(lines) {
        let line: Text = lines[li];
        lineCount = lineCount + 1;
        charCount = charCount + string_len(line);

        let words: Text[] = split(line, " ");
        loop wi in 0..length(words) {
            if string_len(words[wi]) > 0 {
                wordCount = wordCount + 1;
            }
        }
    }

    fx {
        println("Lines: ", lineCount);
        println("Words: ", wordCount);
        println("Chars: ", charCount);
    }
    ret;
}

type Account {
    id: Int;
    owner: Text;
    balance: Real;

    fn deposit(amount: Real) -> Bool {
        if amount <= 0.0 {
            ret false;
        }
        self.balance = self.balance + amount;
        ret true;
    }

    fn withdraw(amount: Real) -> Bool {
        if amount <= 0.0 || amount > self.balance {
            ret false;
        }
        self.balance = self.balance - amount;
        ret true;
    }

    fn transfer(to: Account, amount: Real) -> Bool {
        if !self.withdraw(amount) {
            ret false;
        }
        if !to.deposit(amount) {
            self.deposit(amount);
            ret false;
        }
        ret true;
    }

    fn print() -> Void {
        fx {
            println("Account ", self.id, " (", self.owner, "): ", formatfloat(self.balance, 2));
        }
        ret;
    }
}

fn main() -> Void {
    let alice: Account = new Account { id: 1, owner: "Alice", balance: 1000.0 };
    let bob: Account = new Account { id: 2, owner: "Bob", balance: 500.0 };

    alice.print();
    bob.print();

    alice.deposit(200.0);
    bob.withdraw(100.0);

    alice.transfer(bob, 300.0);

    alice.print();
    bob.print();
    ret;
}

@pure
fn isLeapYear(year: Int) -> Bool {
    if year % 400 == 0 { ret true; }
    if year % 100 == 0 { ret false; }
    if year % 4 == 0 { ret true; }
    ret false;
}

@pure
fn daysInMonth(year: Int, month: Int) -> Int {
    if month == 2 {
        if isLeapYear(year) { ret 29; }
        ret 28;
    }
    if month == 4 || month == 6 || month == 9 || month == 11 {
        ret 30;
    }
    ret 31;
}

@pure
fn dayOfYear(year: Int, month: Int, day: Int) -> Int {
    let total: Int = 0;
    loop m in 1..month + 1 {
        if m < month {
            total = total + daysInMonth(year, m);
        } else {
            total = total + day;
        }
    }
    ret total;
}

@pure
fn addDays(year: Int, month: Int, day: Int, days: Int) -> Text {
    let d: Int = day + days;
    let m: Int = month;
    let y: Int = year;
    loop d > daysInMonth(y, m) {
        d = d - daysInMonth(y, m);
        m = m + 1;
        if m > 12 {
            m = 1;
            y = y + 1;
        }
    }
    ret itoa(y) + "-" + itoa(m) + "-" + itoa(d);
}

fn main() -> Void {
    let year: Int = 2024;
    let month: Int = 3;
    let day: Int = 15;

    fx {
        println("Date: ", year, "-", month, "-", day);
        println("Day of year: ", dayOfYear(year, month, day));
        println("100 days later: ", addDays(year, month, day, 100));
        println("Is 2024 leap? ", isLeapYear(2024));
    }
    ret;
}

type HashEntry {
    key: Text;
    value: Text;
    next: HashEntry;
}

fn makeHashEntry(k: Text, v: Text) -> HashEntry {
    ret new HashEntry { key: k, value: v, next: nil };
}

type HashMap {
    buckets: HashEntry[];
    capacity: Int;

    fn hash(key: Text) -> Int {
        let h: Int = 0;
        let len: Int = string_len(key);
        loop i in 0..len {
            h = h * 31 + ord(copy(key, i + 1, 1));
        }
        if h < 0 { h = -h; }
        ret h % self.capacity;
    }

    fn put(key: Text, value: Text) -> Void {
        let idx: Int = self.hash(key);
        let entry: HashEntry = self.buckets[idx];
        loop entry != nil {
            if entry.key == key {
                entry.value = value;
                ret;
            }
            entry = entry.next;
        }
        let newEntry: HashEntry = makeHashEntry(key, value);
        newEntry.next = self.buckets[idx];
        self.buckets[idx] = newEntry;
        ret;
    }

    fn get(key: Text) -> Text {
        let idx: Int = self.hash(key);
        let entry: HashEntry = self.buckets[idx];
        loop entry != nil {
            if entry.key == key {
                ret entry.value;
            }
            entry = entry.next;
        }
        ret "";
    }

    fn contains(key: Text) -> Bool {
        ret self.get(key) != "";
    }
}

fn makeHashMap(cap: Int) -> HashMap {
    let buckets: HashEntry[] = [];
    loop i in 0..cap {
        buckets = buckets + [nil];
    }
    ret new HashMap { buckets: buckets, capacity: cap };
}

fn main() -> Void {
    let map: HashMap = makeHashMap(16);

    map.put("name", "Alice");
    map.put("city", "Wonderland");
    map.put("age", "30");

    fx {
        println("name: ", map.get("name"));
        println("city: ", map.get("city"));
        println("contains 'age'? ", map.contains("age"));
        println("contains 'email'? ", map.contains("email"));
    }
    ret;
}

type TreeNode {
    value: Int;
    left: TreeNode;
    right: TreeNode;
}

fn makeTreeNode(val: Int) -> TreeNode {
    ret new TreeNode { value: val, left: nil, right: nil };
}

fn insert(root: TreeNode, val: Int) -> TreeNode {
    if root == nil {
        ret makeTreeNode(val);
    }
    if val < root.value {
        root.left = insert(root.left, val);
    } else {
        root.right = insert(root.right, val);
    }
    ret root;
}

fn inorder(root: TreeNode) -> Text {
    if root == nil {
        ret "";
    }
    let result: Text = inorder(root.left);
    result = result + itoa(root.value) + " ";
    result = result + inorder(root.right);
    ret result;
}

fn preorder(root: TreeNode) -> Text {
    if root == nil {
        ret "";
    }
    let result: Text = itoa(root.value) + " ";
    result = result + preorder(root.left);
    result = result + preorder(root.right);
    ret result;
}

fn postorder(root: TreeNode) -> Text {
    if root == nil {
        ret "";
    }
    let result: Text = postorder(root.left);
    result = result + postorder(root.right);
    result = result + itoa(root.value) + " ";
    ret result;
}

fn main() -> Void {
    let root: TreeNode = nil;
    root = insert(root, 50);
    root = insert(root, 30);
    root = insert(root, 70);
    root = insert(root, 20);
    root = insert(root, 40);
    root = insert(root, 60);
    root = insert(root, 80);

    fx {
        println("Inorder:   ", inorder(root));
        println("Preorder:  ", preorder(root));
        println("Postorder: ", postorder(root));
    }
    ret;
}

