@pure
fn is_prime(n: Int) -> Bool {
    if n <= 1 { ret false; }
    if n == 2 { ret true; }
    if n % 2 == 0 { ret false; }
    let max: Int = int(sqrt(real(n)));
    let i: Int = 3;
    loop i <= max {
        if n % i == 0 { ret false; }
        i = i + 2;
    }
    ret true;
}

fn generate_primes(limit: Int) -> Int[] {
    let primes: Int[] = [];
    loop i in 2..limit {
        if is_prime(i) {
            primes = primes + [i];
        }
    }
    ret primes;
}

fn main() -> Void {
    let limit: Int = 50;
    let primes: Int[] = generate_primes(limit);
    fx {
        print("Primes up to ", limit, ": ");
        loop i in 0..length(primes) {
            print(primes[i], " ");
        }
        println("");
    }
    ret;
}

type Json {
    kind: Text;  // "object", "array", "string", "number", "bool", "null"
    value: Text;
    children: Json[];
}

@pure
fn is_digit(ch: Text) -> Bool {
    let code: Int = ord(ch);
    ret code >= 48 && code <= 57;
}

@pure
fn is_number(text: Text) -> Bool {
    loop i in 0..string_len(text) {
        let c: Text = copy(text, i + 1, 1);
        if !is_digit(c) && c != "." && c != "-" {
            ret false;
        }
    }
    ret true;
}

fn parse_json(text: Text) -> Json {
    if text == "null" {
        ret new Json { kind: "null", value: "null", children: [] };
    }
    if text == "true" || text == "false" {
        ret new Json { kind: "bool", value: text, children: [] };
    }
    if is_number(text) {
        ret new Json { kind: "number", value: text, children: [] };
    }
    let len: Int = string_len(text);
    if len >= 2 && copy(text, 1, 1) == "\"" && copy(text, len, 1) == "\"" {
        ret new Json { kind: "string", value: copy(text, 2, len - 2), children: [] };
    }
    ret new Json { kind: "unknown", value: "", children: [] };
}

fn main() -> Void {
    let json_text: Text = "\"Alice\"";
    let json: Json = parse_json(json_text);
    fx {
        println("Parsed JSON kind: ", json.kind);
        println("Parsed JSON value: ", json.value);
    }
    ret;
}

// Grayscale conversion over an in-memory Image. Aether's real file I/O
// (assign/reset/rewrite/readln/writeln) is text-line-oriented, not
// byte-level, so there is no way to parse a binary BMP file from Aether
// source -- this demonstrates the pixel-transform logic on synthetic data
// instead of pretending to load/save a real image file.
type Pixel {
    r: Int;
    g: Int;
    b: Int;
}

type Image {
    width: Int;
    height: Int;
    pixels: Pixel[];
}

fn make_test_image(width: Int, height: Int) -> Image {
    let pixels: Pixel[] = [];
    loop i in 0..width * height {
        pixels = pixels + [new Pixel { r: (i * 37) % 256, g: (i * 59) % 256, b: (i * 83) % 256 }];
    }
    ret new Image { width: width, height: height, pixels: pixels };
}

fn grayscale(image: Image) -> Image {
    let gray_pixels: Pixel[] = [];
    loop i in 0..length(image.pixels) {
        let p: Pixel = image.pixels[i];
        let gray: Int = int(0.299 * real(p.r) + 0.587 * real(p.g) + 0.114 * real(p.b));
        gray_pixels = gray_pixels + [new Pixel { r: gray, g: gray, b: gray }];
    }
    ret new Image { width: image.width, height: image.height, pixels: gray_pixels };
}

fn main() -> Void {
    let image: Image = make_test_image(2, 2);
    let gray: Image = grayscale(image);
    fx {
        loop i in 0..length(gray.pixels) {
            let p: Pixel = gray.pixels[i];
            println("pixel ", i, ": r=", p.r, " g=", p.g, " b=", p.b);
        }
    }
    ret;
}

@pure
fn vigenere_encrypt(text: Text, key: Text) -> Text {
    let result: Text = "";
    let key_len: Int = string_len(key);
    loop i in 0..string_len(text) {
        let c: Int = ord(copy(text, i + 1, 1));
        let k: Int = ord(copy(key, (i % key_len) + 1, 1));
        let encrypted: Int = (c + k - 2 * 97) % 26 + 97;
        result = result + chr(encrypted);
    }
    ret result;
}

@pure
fn vigenere_decrypt(text: Text, key: Text) -> Text {
    let result: Text = "";
    let key_len: Int = string_len(key);
    loop i in 0..string_len(text) {
        let c: Int = ord(copy(text, i + 1, 1));
        let k: Int = ord(copy(key, (i % key_len) + 1, 1));
        let decrypted: Int = (c - k + 26) % 26 + 97;
        result = result + chr(decrypted);
    }
    ret result;
}

fn main() -> Void {
    let plaintext: Text = "hello";
    let key: Text = "secret";
    let ciphertext: Text = vigenere_encrypt(plaintext, key);
    let decrypted: Text = vigenere_decrypt(ciphertext, key);
    fx {
        println("Original: ", plaintext);
        println("Encrypted: ", ciphertext);
        println("Decrypted: ", decrypted);
    }
    ret;
}

// Markov chain over word transitions. Aether has no generic Map<K,V> type
// (no generics at all) and no .contains()/.put()/.get() method-call sugar,
// so transitions are modeled as a linear array of (key, nexts) records
// instead, matching the plain-array idiom used elsewhere in this corpus.
type Transition {
    key: Text;
    nexts: Text[];
}

type MarkovChain {
    transitions: Transition[];
}

fn find_transition(chain: MarkovChain, key: Text) -> Int {
    loop i in 0..length(chain.transitions) {
        if chain.transitions[i].key == key {
            ret i;
        }
    }
    ret -1;
}

fn train(chain: MarkovChain, text: Text) -> Void {
    let words: Text[] = split(text, " ");
    loop i in 0..length(words) - 1 {
        let key: Text = words[i];
        let next: Text = words[i + 1];
        let idx: Int = find_transition(chain, key);
        if idx == -1 {
            chain.transitions = chain.transitions + [new Transition { key: key, nexts: [next] }];
        } else {
            chain.transitions[idx].nexts = chain.transitions[idx].nexts + [next];
        }
    }
    ret;
}

fn generate(chain: MarkovChain, start: Text, length_limit: Int) -> Text {
    let result: Text = start;
    let current: Text = start;
    loop i in 0..length_limit {
        let idx: Int = find_transition(chain, current);
        if idx == -1 {
            break;
        }
        let next_words: Text[] = chain.transitions[idx].nexts;
        let pick: Int = 0;
        fx { pick = random(length(next_words)); }
        current = next_words[pick];
        result = result + " " + current;
    }
    ret result;
}

fn main() -> Void {
    let chain: MarkovChain = new MarkovChain { transitions: [] };
    let text: Text = "the cat sat on the mat the dog sat on the log";
    train(chain, text);

    let generated: Text = "";
    fx {
        randomize();
        generated = generate(chain, "the", 10);
        println("Generated: ", generated);
    }
    ret;
}

fn fetch_url(url: Text) -> Text {
