fn extract_links(html: Text) -> Text[] {
    let links: Text[] = [];
    let remaining: Text = html;
    loop true {
        let marker_pos: Int = pos("<a href=\"", remaining);
        if marker_pos == 0 {
            break;
        }
        let after_marker: Text = copy(remaining, marker_pos + 9, string_len(remaining) - (marker_pos + 9) + 1);
        let end_pos: Int = pos("\"", after_marker);
        if end_pos == 0 {
            break;
        }
        let link: Text = copy(after_marker, 1, end_pos - 1);
        links = links + [link];
        remaining = copy(after_marker, end_pos + 1, string_len(after_marker) - end_pos);
    }
    ret links;
}

fn main() -> Void {
    let url: Text = "http://example.com";
    let html: Text = fetch_url(url);
    let links: Text[] = extract_links(html);
    fx {
        print("Links found: ");
        loop i in 0..length(links) {
            print(links[i], " ");
        }
        println("");
    }
    ret;
}

type Neuron {
    weights: Real[];
    bias: Real;
}

type Layer {
    neurons: Neuron[];
}

type Network {
    layers: Layer[];
}

@pure
fn sigmoid(x: Real) -> Real {
    ret 1.0 / (1.0 + exp(-x));
}

fn forward(network: Network, input: Real[]) -> Real[] {
    let output: Real[] = input;
    loop l in 0..length(network.layers) {
        let layer: Layer = network.layers[l];
        let new_output: Real[] = [];
        loop n in 0..length(layer.neurons) {
            let neuron: Neuron = layer.neurons[n];
            let sum: Real = 0.0;
            loop i in 0..length(output) {
                sum = sum + output[i] * neuron.weights[i];
            }
            sum = sum + neuron.bias;
            new_output = new_output + [sigmoid(sum)];
        }
        output = new_output;
    }
    ret output;
}

fn main() -> Void {
    let network: Network = new Network { layers: [
        new Layer { neurons: [
            new Neuron { weights: [0.5, -0.5], bias: 0.1 },
            new Neuron { weights: [0.3, 0.7], bias: -0.2 }
        ]}
    ]};
    let input: Real[] = [1.0, 2.0];
    let output: Real[] = forward(network, input);
    fx {
        print("Output: ");
        loop i in 0..length(output) {
            print(output[i]:0:4, " ");
        }
        println("");
    }
    ret;
}

type Grid {
    width: Int;
    height: Int;
    cells: Bool[];
}

fn create_grid(width: Int, height: Int) -> Grid {
    let cells: Bool[] = [];
    fx {
        loop y in 0..height {
            loop x in 0..width {
                cells = cells + [random() > 0.7];
            }
        }
    }
    ret new Grid { width: width, height: height, cells: cells };
}

fn count_neighbors(grid: Grid, x: Int, y: Int) -> Int {
    let count: Int = 0;
    loop dy in -1..2 {
        loop dx in -1..2 {
            if dx == 0 && dy == 0 {
                continue;
            }
            let nx: Int = x + dx;
            let ny: Int = y + dy;
            if nx >= 0 && nx < grid.width && ny >= 0 && ny < grid.height {
                let index: Int = ny * grid.width + nx;
                if grid.cells[index] {
                    count = count + 1;
                }
            }
        }
    }
    ret count;
}

fn next_generation(grid: Grid) -> Grid {
    let new_cells: Bool[] = [];
    loop y in 0..grid.height {
        loop x in 0..grid.width {
            let index: Int = y * grid.width + x;
            let neighbors: Int = count_neighbors(grid, x, y);
            if grid.cells[index] {
                new_cells = new_cells + [neighbors == 2 || neighbors == 3];
            } else {
                new_cells = new_cells + [neighbors == 3];
            }
        }
    }
    ret new Grid { width: grid.width, height: grid.height, cells: new_cells };
}

fn print_grid(grid: Grid) -> Void {
    fx {
        loop y in 0..grid.height {
            let row: Text = "";
            loop x in 0..grid.width {
                let index: Int = y * grid.width + x;
                row = row + (if grid.cells[index] { "X" } else { "." });
            }
            println(row);
        }
    }
    ret;
}

fn main() -> Void {
    fx { randomize(); }
    let grid: Grid = create_grid(20, 10);
    loop i in 0..3 {
        print_grid(grid);
        grid = next_generation(grid);
    }
    ret;
}

// A minimal test runner. Aether has no function values (FUNC-001) -- no
// closures, no fn-typed fields -- so tests can't be stored as
// Test { fn: () -> Bool } records. Each test's boolean result is computed
// directly and reported through a small helper instead.
fn report(name: Text, passed: Bool, passCount: Int, failCount: Int) -> Int[] {
    fx {
        if passed {
            println("[PASS] ", name);
        } else {
            println("[FAIL] ", name);
        }
    }
    if passed {
        ret [passCount + 1, failCount];
    }
    ret [passCount, failCount + 1];
}

fn main() -> Void {
    let passCount: Int = 0;
    let failCount: Int = 0;

    let r1: Int[] = report("2 + 2 = 4", 2 + 2 == 4, passCount, failCount);
    passCount = r1[0]; failCount = r1[1];

    let r2: Int[] = report("5 > 3", 5 > 3, passCount, failCount);
    passCount = r2[0]; failCount = r2[1];

    let r3: Int[] = report("Hello starts with H", copy("Hello", 1, 1) == "H", passCount, failCount);
    passCount = r3[0]; failCount = r3[1];

    fx {
        println("Passed: ", passCount, "/", passCount + failCount);
    }
    ret;
}

