fn merge(left: Int[], right: Int[]) -> Int[] {
    let result: Int[] = [];
    let i: Int = 0;
    let j: Int = 0;
    loop i < length(left) && j < length(right) {
        if left[i] <= right[j] {
            result = result + [left[i]];
            i = i + 1;
        } else {
            result = result + [right[j]];
            j = j + 1;
        }
    }
    loop i < length(left) {
        result = result + [left[i]];
        i = i + 1;
    }
    loop j < length(right) {
        result = result + [right[j]];
        j = j + 1;
    }
    ret result;
}

fn merge_sort(arr: Int[]) -> Int[] {
    if length(arr) <= 1 {
        ret arr;
    }
    let mid: Int = length(arr) / 2;
    let left: Int[] = [];
    let right: Int[] = [];
    loop i in 0..mid {
        left = left + [arr[i]];
    }
    loop i in mid..length(arr) {
        right = right + [arr[i]];
    }
    left = merge_sort(left);
    right = merge_sort(right);
    ret merge(left, right);
}

fn main() -> Void {
    let nums: Int[] = [61, 12, 88, 5, 39, 24, 70];
    let sorted: Int[] = merge_sort(nums);

    fx {
        print("Sorted: ");
        loop i in 0..length(sorted) {
            print(sorted[i], " ");
        }
        println("");
    }
    ret;
}

type Matrix {
    rows: Int;
    cols: Int;
    data: Real[][];

    fn init(r: Int, c: Int) -> Void {
        self.rows = r;
        self.cols = c;
        self.data = [];
        loop i in 0..r {
            let row: Real[] = [];
            loop j in 0..c {
                row = row + [0.0];
            }
            self.data = self.data + [row];
        }
        ret;
    }

    fn set(r: Int, c: Int, val: Real) -> Void {
        self.data[r][c] = val;
        ret;
    }

    fn get(r: Int, c: Int) -> Real {
        ret self.data[r][c];
    }

    fn multiply(other: Matrix) -> Matrix {
        let result: Matrix = new Matrix {};
        result.init(self.rows, other.cols);
        loop i in 0..self.rows {
            loop j in 0..other.cols {
                let sum: Real = 0.0;
                loop k in 0..self.cols {
                    sum = sum + self.data[i][k] * other.data[k][j];
                }
                result.set(i, j, sum);
            }
        }
        ret result;
    }

    fn print_matrix() -> Void {
        loop i in 0..self.rows {
            let line: Text = "";
            loop j in 0..self.cols {
                line = line + formatfloat(self.data[i][j], 2) + "  ";
            }
            fx {
                println(line);
            }
        }
        ret;
    }
}

fn main() -> Void {
    let a: Matrix = new Matrix {};
    a.init(2, 3);
    a.set(0, 0, 1.0); a.set(0, 1, 2.0); a.set(0, 2, 3.0);
    a.set(1, 0, 4.0); a.set(1, 1, 5.0); a.set(1, 2, 6.0);

    let b: Matrix = new Matrix {};
    b.init(3, 2);
    b.set(0, 0, 7.0); b.set(0, 1, 8.0);
    b.set(1, 0, 9.0); b.set(1, 1, 10.0);
    b.set(2, 0, 11.0); b.set(2, 1, 12.0);

    let c: Matrix = a.multiply(b);

    fx {
        println("Matrix A * B =");
    }
    c.print_matrix();
    ret;
}

type FSNode {
    name: Text;
    is_dir: Bool;
    content: Text;
    children: FSNode[];

    fn init(name: Text, is_dir: Bool) -> Void {
        self.name = name;
        self.is_dir = is_dir;
        self.content = "";
        self.children = [];
        ret;
    }

    fn find_child(name: Text) -> FSNode {
        loop i in 0..length(self.children) {
            if self.children[i].name == name {
                ret self.children[i];
            }
        }
        ret new FSNode {};
    }

    fn mkdir(name: Text) -> Bool {
        let dir: FSNode = new FSNode {};
        dir.init(name, true);
        self.children = self.children + [dir];
        ret true;
    }

    fn create_file(name: Text, content: Text) -> Bool {
        let file: FSNode = new FSNode {};
        file.init(name, false);
        file.content = content;
        self.children = self.children + [file];
        ret true;
    }

    fn list(indent: Text) -> Void {
        let suffix: Text = "";
        if self.is_dir {
            suffix = "/";
        }
        fx {
            println(indent + self.name + suffix);
        }
        if self.is_dir {
            loop i in 0..length(self.children) {
                self.children[i].list(indent + "  ");
            }
        }
        ret;
    }
}

fn main() -> Void {
    let root: FSNode = new FSNode {};
    root.init("/", true);

    root.mkdir("home");
    let home: FSNode = root.find_child("home");
    home.mkdir("user");
    let user: FSNode = home.find_child("user");
    user.create_file("readme.txt", "Hello Aether!");
    user.mkdir("projects");
    let projects: FSNode = user.find_child("projects");
    projects.create_file("main.ae", "fn main() {}");
    root.mkdir("etc");
    let etc: FSNode = root.find_child("etc");
    etc.create_file("config.cfg", "debug=true");

    fx {
        println("File system tree:");
    }
    root.list("");
    ret;
}

type Room {
    name: Text;
    description: Text;
    exits: Text[];
    exit_dests: Int[];
    visited: Bool;
}

type Game {
    rooms: Room[];
    current_room: Int;
    player_inventory: Text[];
    game_over: Bool;

    fn init() -> Void {
        self.rooms = [];
        self.current_room = 0;
        self.player_inventory = [];
        self.game_over = false;
        ret;
    }

    fn add_room(name: Text, desc: Text) -> Int {
        let r: Room = new Room {};
        r.name = name;
        r.description = desc;
        r.exits = [];
        r.exit_dests = [];
        r.visited = false;
        self.rooms = self.rooms + [r];
        ret length(self.rooms) - 1;
    }

    fn add_exit(from_room: Int, direction: Text, to_room: Int) -> Void {
        self.rooms[from_room].exits = self.rooms[from_room].exits + [direction];
        self.rooms[from_room].exit_dests = self.rooms[from_room].exit_dests + [to_room];
        ret;
    }

    fn describe() -> Void {
        let r: Room = self.rooms[self.current_room];
        fx {
            println("");
            println("== ", r.name, " ==");
            println(r.description);
        }
        if length(r.exits) > 0 {
            let exits_str: Text = "Exits: ";
            loop i in 0..length(r.exits) {
                exits_str = exits_str + r.exits[i] + " ";
            }
            fx {
                println(exits_str);
            }
        }
        ret;
    }

    fn move(direction: Text) -> Bool {
        let r: Room = self.rooms[self.current_room];
        loop i in 0..length(r.exits) {
            if r.exits[i] == direction {
                self.current_room = r.exit_dests[i];
                ret true;
            }
        }
        fx {
            println("You can't go that way.");
        }
        ret false;
    }

    fn take_item(item: Text) -> Void {
        self.player_inventory = self.player_inventory + [item];
        fx {
            println("You picked up: ", item);
        }
        ret;
    }

    fn show_inventory() -> Void {
        fx {
            if length(self.player_inventory) == 0 {
                println("Your inventory is empty.");
            } else {
                println("Inventory:");
                loop i in 0..length(self.player_inventory) {
                    println("  ", self.player_inventory[i]);
                }
            }
        }
        ret;
    }
}

fn main() -> Void {
    let g: Game = new Game {};
    g.init();

    let entrance: Int = g.add_room("Entrance Hall", "A grand hall with marble floors. Dust hangs in the air.");
    let library: Int = g.add_room("Library", "Shelves of ancient books stretch to the ceiling. A golden key rests on a table.");
    let dungeon: Int = g.add_room("Dungeon", "Cold stone walls. A locked door leads further, but you need a key.");
    let treasure: Int = g.add_room("Treasure Room", "Piles of gold and jewels surround you. You've won!");

    g.add_exit(entrance, "north", library);
    g.add_exit(entrance, "down", dungeon);
    g.add_exit(library, "south", entrance);
    g.add_exit(dungeon, "up", entrance);
    g.add_exit(dungeon, "north", treasure);

    g.describe();
    let moved1: Bool = g.move("north");
    g.describe();
    g.take_item("golden key");
    g.show_inventory();
    let moved2: Bool = g.move("south");
    let moved3: Bool = g.move("down");
    g.describe();
    let moved4: Bool = g.move("north");
    g.describe();

    ret;
}
